<?php
$activePage='alumni';$pageTitle='Profil Alumni | '.APP_NAME;$pageDescription='Profil dan perjalanan para alumni Pondok Pesantren Ash-Shiddiq.';$pageCanonical=BASE_URL.'/alumni';$alumni=[];
try{$alumni=getDB()->query("SELECT nama,tahun_kelulusan,alamat,aktivitas,tempat_kuliah,jurusan,tempat_bekerja,jabatan,pesan_kesan,foto,orientasi FROM alumni WHERE status='verified' AND tampil_landing=1 ORDER BY tahun_kelulusan DESC,nama ASC")->fetchAll();}catch(PDOException $e){}
?>
<main class="page-section alumni-profile-page"><div class="container"><div class="section-tag" style="justify-content:center"><span></span><span class="section-tag-text">Jejak Alumni</span><span></span></div><h1 class="section-title" style="text-align:center">Profil Para Alumni</h1><p class="section-desc" style="text-align:center;margin:0 auto">Mengenal perjalanan para alumni Ash-Shiddiq setelah menyelesaikan pendidikan di pesantren.</p>
<div class="alumni-profile-grid"><?php foreach($alumni as $a):$orientasi=$a['orientasi']??'landscape';?><article class="alumni-profile-card <?=$orientasi?>"><img src="<?=e(BASE_URL.'/uploads/alumni/'.$a['foto'])?>" alt="Foto <?=e($a['nama'])?>" loading="lazy"><div class="alumni-profile-body"><span class="alumni-year">Angkatan <?=e((string)$a['tahun_kelulusan'])?></span><h2><?=e($a['nama'])?></h2><p class="alumni-current"><strong><?=e($a['aktivitas']==='kuliah'?'Kuliah':'Bekerja')?>:</strong> <?=e($a['aktivitas']==='kuliah'?$a['tempat_kuliah'].' — '.$a['jurusan']:$a['tempat_bekerja'].' — '.$a['jabatan'])?></p><blockquote>“<?=e($a['pesan_kesan'])?>”</blockquote></div></article><?php endforeach;?></div>
<?php if(!$alumni):?><div class="empty-state" style="margin-top:35px">Profil alumni sedang disiapkan.</div><?php endif;?><div class="alumni-submit-cta"><p>Anda alumni Ash-Shiddiq dan belum tercatat?</p><a class="btn-primary" href="<?=BASE_URL?>/pendataan-alumni">Isi Pendataan Alumni</a></div></div></main>
